<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/session.php'; require_once __DIR__ . '/includes/helpers.php'; require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/csrf.php'; require_once __DIR__ . '/includes/booking.php';
require_login(); $resource_id = (int) ($_SESSION['booking']['resource_id'] ?? 0); $statement = db()->prepare('SELECT * FROM resources WHERE id = ? AND is_active = 1'); $statement->execute([$resource_id]); $resource = $statement->fetch(); if (!$resource) { redirect('booking-step-1.php'); }
$date = (string) ($_POST['booking_date'] ?? $_SESSION['booking']['booking_date'] ?? date('Y-m-d')); $occupied = valid_date($date) ? occupied_slots($resource_id, $date) : [];
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $start = (string) ($_POST['start_time'] ?? ''); if (!valid_date($date) || !array_key_exists($start, slot_options())) { flash('danger', 'Bitte wählen Sie ein gültiges zukünftiges Datum und einen gültigen Zeitslot.'); } elseif (in_array($start, occupied_slots($resource_id, $date), true)) { flash('danger', 'Dieser Zeitslot ist inzwischen belegt. Bitte wählen Sie einen anderen.'); } else { $_SESSION['booking']['booking_date'] = $date; $_SESSION['booking']['start_time'] = $start; $_SESSION['booking']['end_time'] = slot_options()[$start]; redirect('booking-step-3.php'); } }
$page_title = 'Datum und Zeitslot'; require __DIR__ . '/includes/header.php';
?><p class="step-indicator">Schritt 2 von 4 · <?= e($resource['name']) ?></p><h1>Datum und Zeitslot</h1><form method="post" class="form-panel"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="mb-4"><label class="form-label" for="booking_date">Datum</label><input class="form-control" id="booking_date" name="booking_date" type="date" min="<?= e(date('Y-m-d')) ?>" value="<?= e($date) ?>" required><button class="btn btn-outline-primary mt-2" type="button" onclick="this.form.submit()">Verfügbarkeit anzeigen</button></div><fieldset><legend class="h5">Feste Zeitslots</legend><?php foreach (slot_options() as $start => $end): $is_occupied = in_array($start, $occupied, true); ?><label class="d-block border rounded p-3 mb-2 <?= $is_occupied ? 'text-muted bg-light' : '' ?>"><input type="radio" name="start_time" value="<?= e($start) ?>" <?= $is_occupied ? 'disabled' : '' ?> required> <?= e($start) ?> bis <?= e($end) ?> <?php if ($is_occupied): ?><span class="badge text-bg-secondary">belegt</span><?php else: ?><span class="badge text-bg-success">verfügbar</span><?php endif; ?></label><?php endforeach; ?></fieldset><button class="btn btn-primary mt-3" type="submit">Extras auswählen</button></form>
